-- Apache-2.0 licensed PostgreSQL schema; no warranty.
-- Runtime startup uses SQLAlchemy metadata; this migration documents the deployable baseline.
CREATE TABLE IF NOT EXISTS cases (id varchar(36) PRIMARY KEY, tenant_id varchar(255) NOT NULL, title varchar(500) NOT NULL, description text, deadline timestamptz NOT NULL, current_revision integer NOT NULL DEFAULT 0, status varchar(20) NOT NULL DEFAULT 'draft', owner_id varchar(255) NOT NULL, created_at timestamptz NOT NULL);
CREATE INDEX IF NOT EXISTS ix_cases_tenant_id ON cases(tenant_id);
CREATE TABLE IF NOT EXISTS revisions (id varchar(36) PRIMARY KEY, case_id varchar(36) NOT NULL REFERENCES cases(id) ON DELETE CASCADE, tenant_id varchar(255) NOT NULL, number integer NOT NULL, deadline timestamptz NOT NULL, reason text NOT NULL, created_by varchar(255) NOT NULL, created_at timestamptz NOT NULL, UNIQUE(case_id, number));
CREATE TABLE IF NOT EXISTS requirements (id varchar(36) PRIMARY KEY, case_id varchar(36) NOT NULL REFERENCES cases(id) ON DELETE CASCADE, revision_id varchar(36) NOT NULL REFERENCES revisions(id) ON DELETE CASCADE, tenant_id varchar(255) NOT NULL, revision integer NOT NULL, key varchar(255) NOT NULL, title varchar(500) NOT NULL, description text NOT NULL, kind varchar(20) NOT NULL, minimum integer, mandatory boolean NOT NULL, source_ref varchar(1000) NOT NULL, owner varchar(255) NOT NULL, status varchar(20) NOT NULL, UNIQUE(case_id, revision_id, key));
CREATE TABLE IF NOT EXISTS evidence (id varchar(36) PRIMARY KEY, case_id varchar(36) NOT NULL REFERENCES cases(id) ON DELETE CASCADE, tenant_id varchar(255) NOT NULL, requirement_key varchar(255) NOT NULL, filename varchar(500) NOT NULL, sha256 varchar(64) NOT NULL, object_key varchar(1000) NOT NULL, valid_until timestamptz, quantity integer, notes text, verified boolean NOT NULL, uploaded_by varchar(255) NOT NULL, verified_by varchar(255), revision integer NOT NULL, created_at timestamptz NOT NULL, UNIQUE(case_id, revision, sha256));
CREATE TABLE IF NOT EXISTS tasks (id varchar(36) PRIMARY KEY, case_id varchar(36) NOT NULL REFERENCES cases(id) ON DELETE CASCADE, tenant_id varchar(255) NOT NULL, revision integer NOT NULL, requirement_key varchar(255) NOT NULL, title varchar(500) NOT NULL, status varchar(20) NOT NULL, assignee varchar(255), created_at timestamptz NOT NULL, UNIQUE(case_id, revision, requirement_key));
CREATE TABLE IF NOT EXISTS comments (id varchar(36) PRIMARY KEY, case_id varchar(36) NOT NULL REFERENCES cases(id) ON DELETE CASCADE, tenant_id varchar(255) NOT NULL, author varchar(255) NOT NULL, body text NOT NULL, created_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS approvals (id varchar(36) PRIMARY KEY, case_id varchar(36) NOT NULL REFERENCES cases(id) ON DELETE CASCADE, tenant_id varchar(255) NOT NULL, revision integer NOT NULL, reviewer_id varchar(255) NOT NULL, decision varchar(20) NOT NULL, comment text NOT NULL, workflow_id varchar(255), created_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS impacts (id varchar(36) PRIMARY KEY, case_id varchar(36) NOT NULL REFERENCES cases(id) ON DELETE CASCADE, tenant_id varchar(255) NOT NULL, revision integer NOT NULL, requirement_key varchar(255) NOT NULL, kind varchar(50) NOT NULL, detail text NOT NULL, created_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS notices (id varchar(36) PRIMARY KEY, case_id varchar(36) NOT NULL REFERENCES cases(id) ON DELETE CASCADE, tenant_id varchar(255) NOT NULL, publication_number varchar(255) NOT NULL, source_graph varchar(1000) NOT NULL, retrieved_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS outbox_events (id varchar(36) PRIMARY KEY, tenant_id varchar(255) NOT NULL, subject varchar(255) NOT NULL, payload text NOT NULL, delivered_at timestamptz, created_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS audit_events (id varchar(36) PRIMARY KEY, tenant_id varchar(255) NOT NULL, actor_id varchar(255) NOT NULL, action varchar(255) NOT NULL, entity_type varchar(100) NOT NULL, entity_id varchar(255) NOT NULL, payload text NOT NULL, previous_hash varchar(64) NOT NULL, hash varchar(64) NOT NULL, created_at timestamptz NOT NULL);
